(function() {
  var __sections__ = {};
  (function() {
    for(var i = 0, s = document.getElementById('sections-script').getAttribute('data-sections').split(','); i < s.length; i++)
      __sections__[s[i]] = true;
    })();
    (function() {
  if (!__sections__["brunito-comunidad-article"]) return;
  try {
    
  document.querySelectorAll('[data-copy-article-link]').forEach((button) => {
    button.addEventListener('click', async () => {
      const url = button.dataset.copyArticleLink;
      const status = button.closest('.brunito-community-article__share')?.querySelector('[data-copy-article-status]');
      const defaultLabel = button.dataset.copyLabel;

      try {
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(url);
        } else {
          const helper = document.createElement('textarea');
          helper.value = url;
          helper.style.position = 'fixed';
          helper.style.opacity = '0';
          document.body.appendChild(helper);
          helper.select();
          document.execCommand('copy');
          helper.remove();
        }

        button.textContent = 'Enlace copiado';
        if (status) status.textContent = 'El enlace de este artículo se ha copiado.';
      } catch {
        if (status) status.textContent = 'No se ha podido copiar. Puedes copiar la dirección desde el navegador.';
      }

      window.setTimeout(() => {
        button.textContent = defaultLabel;
      }, 2400);
    });
  });

  } catch(e) { console.error(e); }
})();

(function() {
  if (!__sections__["brunito-judge-me-reviews"]) return;
  try {
    
  (() => {
    const reviewWidgetSelector = '#judgeme_product_reviews';
    const folderIcon = '<svg class="brunito-review-media-toggle__icon" viewBox="0 0 20 16" fill="none" aria-hidden="true"><path d="M1.25 3.25A1.75 1.75 0 0 1 3 1.5h4l1.65 1.75h8.6A1.75 1.75 0 0 1 19 5v8.25A1.75 1.75 0 0 1 17.25 15H2.75A1.75 1.75 0 0 1 1 13.25V3.25Z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>';
    const galleryFolderIcon = '<svg class="brunito-gallery-toggle__icon" viewBox="0 0 20 16" fill="none" aria-hidden="true"><path d="M1.25 3.25A1.75 1.75 0 0 1 3 1.5h4l1.65 1.75h8.6A1.75 1.75 0 0 1 19 5v8.25A1.75 1.75 0 0 1 17.25 15H2.75A1.75 1.75 0 0 1 1 13.25V3.25Z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>';
    const pencilIcon = '<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m4 14.9.75-3.35L13.7 2.6a1.65 1.65 0 0 1 2.35 0l1.35 1.35a1.65 1.65 0 0 1 0 2.35l-8.95 8.95L5.1 16 4 14.9Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/><path d="m11.9 4.4 3.7 3.7" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';
    const setPhotoButtonLabel = (button, label, icon) => {
      if (button.getAttribute('aria-label') === label && button.querySelector('svg')) return;
      button.setAttribute('aria-label', label);
      button.innerHTML = `${icon}<span class="visually-hidden">${label}</span>`;
    };

    const compactReviewAction = (button) => {
      if (button.dataset.brunitoCompactAction === 'true') return;
      button.dataset.brunitoCompactAction = 'true';
      button.setAttribute('aria-label', 'Escribir una reseña');
      button.innerHTML = `${pencilIcon}<span class="visually-hidden">Escribir una reseña</span>`;
    };

    const ensureReviewDialog = (widget) => {
      let dialog = widget.dataset.brunitoReviewDialogId
        ? document.getElementById(widget.dataset.brunitoReviewDialogId)
        : null;
      if (dialog) return dialog;

      dialog = document.createElement('dialog');
      dialog.className = 'brunito-review-dialog';
      dialog.id = `brunito-review-dialog-${Math.random().toString(36).slice(2)}`;
      dialog.innerHTML = `
        <div class="brunito-review-dialog__panel">
          <header class="brunito-review-dialog__header">
            <h2 class="brunito-review-dialog__title">Reseña completa</h2>
            <button class="brunito-review-dialog__close" type="button" aria-label="Cerrar">×</button>
          </header>
          <div class="brunito-review-dialog__content"></div>
        </div>
      `;
      document.body.append(dialog);

      const closeButton = dialog.querySelector('.brunito-review-dialog__close');
      closeButton?.addEventListener('click', () => dialog.close());
      dialog.addEventListener('click', (event) => {
        if (event.target === dialog) dialog.close();
      });
      dialog.addEventListener('close', () => dialog._brunitoReturnTo?.focus({ preventScroll: true }));
      widget.dataset.brunitoReviewDialogId = dialog.id;

      return dialog;
    };

    const openReviewDialog = (widget, review) => {
      const dialog = ensureReviewDialog(widget);
      const content = dialog.querySelector('.brunito-review-dialog__content');
      const title = dialog.querySelector('.brunito-review-dialog__title');
      if (!content || !title) return;

      const reviewerName = review.querySelector('.jm-reviewer-info__name')?.textContent?.trim();
      title.textContent = reviewerName ? `Reseña de ${reviewerName}` : 'Reseña completa';
      const clone = review.cloneNode(true);
      clone.removeAttribute('id');
      clone.querySelectorAll('[id]').forEach((element) => element.removeAttribute('id'));
      clone.removeAttribute('tabindex');
      clone.removeAttribute('role');
      clone.removeAttribute('aria-label');
      content.replaceChildren(clone);
      dialog._brunitoReturnTo = review;

      if (!dialog.open) dialog.showModal();
      dialog.querySelector('.brunito-review-dialog__close')?.focus();
    };

    const setupReviewInteractions = (widget) => {
      widget.querySelectorAll('.jm-review-item').forEach((review) => {
        if (review.dataset.brunitoReviewClickable === 'true') return;
        review.dataset.brunitoReviewClickable = 'true';
        review.setAttribute('role', 'button');
        review.setAttribute('tabindex', '0');
        review.setAttribute('aria-haspopup', 'dialog');
        review.setAttribute('aria-label', 'Abrir reseña completa');

        const open = (event) => {
          if (event.target.closest('button, a, input, select, textarea, summary')) return;
          openReviewDialog(widget, review);
        };

        review.addEventListener('click', open);
        review.addEventListener('keydown', (event) => {
          if (event.key !== 'Enter' && event.key !== ' ') return;
          event.preventDefault();
          openReviewDialog(widget, review);
        });
      });
    };

    const setupReviewCarousel = (widget) => {
      const header = widget.querySelector('.jm-review-widget__header');
      const body = widget.querySelector('.jm-review-widget__body');
      const list = widget.querySelector('.jdgm-review-list');
      if (!header || !body || !list) return;

      list.classList.add('brunito-review-carousel');
      body.id ||= `brunito-review-body-${Math.random().toString(36).slice(2)}`;

      let allReviewsButton = header.querySelector('.brunito-review-all');
      if (!allReviewsButton) {
        allReviewsButton = document.createElement('button');
        allReviewsButton.className = 'brunito-review-all';
        allReviewsButton.type = 'button';
        allReviewsButton.setAttribute('aria-controls', body.id);
        allReviewsButton.setAttribute('aria-expanded', 'false');
        allReviewsButton.textContent = 'Ver todas las reseñas';
        allReviewsButton.addEventListener('click', () => {
          const expanded = widget.classList.toggle('brunito-reviews-expanded');
          allReviewsButton.setAttribute('aria-expanded', String(expanded));
          allReviewsButton.textContent = expanded ? 'Ocultar reseñas' : 'Ver todas las reseñas';
          if (expanded) body.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
        header.append(allReviewsButton);
      }

      const reviewItems = [...list.querySelectorAll('.jm-review-item')];
      if (!reviewItems.length) return;

      let dots = widget.querySelector('.brunito-review-dots');
      const dotCount = Math.min(3, Math.max(1, reviewItems.length));
      if (!dots) {
        dots = document.createElement('div');
        dots.className = 'brunito-review-dots';
        dots.setAttribute('aria-hidden', 'true');
        body.after(dots);
      }

      if (dots.children.length !== dotCount) {
        dots.replaceChildren(...Array.from({ length: dotCount }, () => document.createElement('span')));
      }

      const updateDots = () => {
        const pageWidth = Math.max(1, list.clientWidth);
        const activeIndex = Math.min(dotCount - 1, Math.round(list.scrollLeft / pageWidth));
        [...dots.children].forEach((dot, index) => dot.classList.toggle('is-active', index === activeIndex));
      };

      if (list.dataset.brunitoScrollBound !== 'true') {
        list.addEventListener('scroll', updateDots, { passive: true });
        window.addEventListener('resize', updateDots, { passive: true });
        list.dataset.brunitoScrollBound = 'true';
      }

      updateDots();
    };

    const setupGalleryCarousel = (gallery) => {
      const track = gallery.querySelector('.jm-media-grid__container');
      if (!track || gallery.querySelector('.brunito-gallery-carousel-controls')) return;

      track.id ||= `brunito-gallery-track-${Math.random().toString(36).slice(2)}`;
      const controls = document.createElement('div');
      controls.className = 'brunito-gallery-carousel-controls';
      controls.innerHTML = '<button class="brunito-gallery-carousel-button" type="button" aria-label="Foto anterior"><svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m9.75 3.25-4.5 4.5 4.5 4.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button class="brunito-gallery-carousel-button" type="button" aria-label="Foto siguiente"><svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m6.25 3.25 4.5 4.5-4.5 4.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button>';

      const previousButton = controls.querySelector('[aria-label="Foto anterior"]');
      const nextButton = controls.querySelector('[aria-label="Foto siguiente"]');
      const getScrollStep = () => {
        const firstItem = track.querySelector('.jm-media-grid__item');
        if (!firstItem) return track.clientWidth * 0.75;

        const itemWidth = firstItem.getBoundingClientRect().width;
        const gap = Number.parseFloat(getComputedStyle(track).gap) || 0;
        return itemWidth + gap;
      };

      previousButton?.addEventListener('click', () => track.scrollBy({ left: -getScrollStep(), behavior: 'smooth' }));
      nextButton?.addEventListener('click', () => track.scrollBy({ left: getScrollStep(), behavior: 'smooth' }));
      gallery.append(controls);
    };

    const createAverageStars = (ratingDisplay) => {
      const existingStars = ratingDisplay.querySelector('.brunito-average-stars');
      const ratingMatch = ratingDisplay.textContent.match(/\d+(?:[.,]\d+)?/);
      const rating = ratingMatch ? Number(ratingMatch[0].replace(',', '.')) : null;

      if (!Number.isFinite(rating)) return;

      const filledStars = Math.max(0, Math.min(5, Math.round(rating)));
      const starMarkup = `${'<span>★</span>'.repeat(filledStars)}${'<span class="brunito-average-stars__empty">★</span>'.repeat(5 - filledStars)}`;

      if (existingStars) {
        if (existingStars.dataset.rating !== String(rating)) {
          existingStars.innerHTML = starMarkup;
          existingStars.dataset.rating = String(rating);
        }
        return;
      }

      const stars = document.createElement('span');
      stars.className = 'brunito-average-stars';
      stars.setAttribute('aria-hidden', 'true');
      stars.innerHTML = starMarkup;
      stars.dataset.rating = String(rating);
      ratingDisplay.append(stars);
    };

    const setupGallery = (widget) => {
      const gallery = widget.querySelector('.jm-media-preview');
      const header = widget.querySelector('.jm-review-widget__header');

      if (!gallery || !header) return;

      gallery.id ||= 'brunito-review-gallery';
      const imageCount = gallery.querySelectorAll('.jm-media-grid__item').length;
      let galleryButton = header.querySelector('.brunito-gallery-toggle');

      if (imageCount > 0) {
        gallery.classList.add('brunito-photo-carousel');
        setupGalleryCarousel(gallery);
      }

      if (!galleryButton) {
        galleryButton = document.createElement('button');
        galleryButton.className = 'brunito-gallery-toggle';
        galleryButton.type = 'button';
        galleryButton.setAttribute('aria-controls', gallery.id);
        gallery.hidden = true;

        galleryButton.addEventListener('click', () => {
          const isExpanded = galleryButton.getAttribute('aria-expanded') === 'true';
          gallery.hidden = isExpanded;
          galleryButton.setAttribute('aria-expanded', String(!isExpanded));
          setPhotoButtonLabel(galleryButton, isExpanded ? galleryButton.dataset.showLabel : 'Ocultar fotos de clientas', galleryFolderIcon);
        });

        const actionGroup = header.querySelector('.jm-review-widget-minimal-header__button-and-filters, .jm-action-buttons');
        (actionGroup || header).append(galleryButton);
      }

      const showLabel = imageCount > 0
        ? `Ver fotos de clientas (${imageCount})`
        : 'Ver fotos de clientas';

      const buttonLabel = gallery.hidden ? showLabel : 'Ocultar fotos de clientas';

      galleryButton.dataset.showLabel = showLabel;
      galleryButton.setAttribute('aria-controls', gallery.id);
      galleryButton.setAttribute('aria-expanded', String(!gallery.hidden));
      setPhotoButtonLabel(galleryButton, buttonLabel, galleryFolderIcon);
    };

    const setupWidget = (widget) => {
      const noReviewsState = widget.querySelector('.jm-no-reviews-state');
      const noReviewsIntro = noReviewsState?.querySelector('.jm-no-reviews-state__text');
      const emptyStateMessage = widget.querySelector('.jdgm-empty-state .jm-text, .jdgm-empty-state p');

      if (noReviewsIntro && !noReviewsIntro.hidden) noReviewsIntro.hidden = true;
      if (emptyStateMessage && emptyStateMessage.textContent.trim() !== 'Aún no hay reseñas disponibles.') {
        emptyStateMessage.textContent = 'Aún no hay reseñas disponibles.';
      }

      const averageRating = widget.querySelector('.jm-average-rating-display');
      if (averageRating) createAverageStars(averageRating);

      widget.querySelectorAll('.jm-review-widget__header .jm-button--primary, .jm-no-reviews-state .jm-button--primary').forEach(compactReviewAction);

      widget.querySelectorAll('.jm-review-item').forEach((review) => {
        const rating = review.querySelector('.jm-star-rating');
        const reviewer = review.querySelector('.jm-reviewer-info');
        if (rating && reviewer && rating.parentElement !== reviewer) reviewer.append(rating);

        const mediaItems = review.querySelectorAll('.jm-media-thumbnail-list__thumbnail');
        const mediaContainer = review.querySelector('.jm-media-thumbnail-list') || mediaItems[0]?.closest('.jm-cluster');
        const mediaCount = mediaItems.length;

        if (mediaContainer && mediaCount > 0) {
          mediaContainer.classList.add('brunito-review-media-container');
          mediaContainer.id ||= `brunito-review-media-${mediaContainer.dataset.reviewId || Math.random().toString(36).slice(2)}`;
          mediaContainer.dataset.reviewId = mediaContainer.id.replace('brunito-review-media-', '');

          let mediaButton = review.querySelector('.brunito-review-media-toggle');
          const mediaLabel = `Ver fotos (${mediaCount})`;

          if (!mediaButton) {
            mediaButton = document.createElement('button');
            mediaButton.className = 'brunito-review-media-toggle';
            mediaButton.type = 'button';
            mediaButton.innerHTML = `${folderIcon}<span class="brunito-review-media-toggle__label"></span>`;
            mediaContainer.hidden = true;

            mediaButton.addEventListener('click', () => {
              const isExpanded = mediaButton.getAttribute('aria-expanded') === 'true';
              mediaContainer.hidden = isExpanded;
              mediaButton.setAttribute('aria-expanded', String(!isExpanded));
              setPhotoButtonLabel(mediaButton, isExpanded ? mediaButton.dataset.showLabel : 'Ocultar fotos', folderIcon);
            });

            mediaContainer.before(mediaButton);
          }

          mediaButton.dataset.showLabel = mediaLabel;
          mediaButton.setAttribute('aria-controls', mediaContainer.id);
          mediaButton.setAttribute('aria-expanded', String(!mediaContainer.hidden));
          const visibleLabel = mediaContainer.hidden ? mediaLabel : 'Ocultar fotos';
          setPhotoButtonLabel(mediaButton, visibleLabel, folderIcon);
        }
      });

      widget.querySelectorAll('.jm-button--secondary').forEach((button) => {
        if (!button.getAttribute('aria-label')) button.setAttribute('aria-label', 'Filtrar reseñas');
      });

      widget.querySelectorAll('.jm-review-widget-minimal-header__filter-container select, .jm-review-widget-minimal-header__filter-container [role="combobox"]').forEach((control) => {
        if (!control.getAttribute('aria-label')) control.setAttribute('aria-label', 'Ordenar reseñas');
      });

      setupGallery(widget);
      setupReviewInteractions(widget);
      const header = widget.querySelector('.jm-review-widget__header');
      if (header) {
        let toolbar = header.querySelector('.brunito-review-toolbar');
        if (!toolbar) {
          toolbar = document.createElement('div');
          toolbar.className = 'brunito-review-toolbar';
          header.append(toolbar);
        }
        header.querySelectorAll('.jm-button--primary, .jm-button--secondary, select, .brunito-gallery-toggle').forEach((control) => {
          if (control.parentElement !== toolbar) toolbar.append(control);
        });
      }

      setupReviewCarousel(widget);
    };

    const initializeWidgets = () => document.querySelectorAll(reviewWidgetSelector).forEach((widget) => {
      setupWidget(widget);

      if (widget.dataset.brunitoObserver) return;
      const observer = new MutationObserver(() => setupWidget(widget));
      observer.observe(widget, { childList: true, subtree: true });
      widget.dataset.brunitoObserver = 'true';
    });

    initializeWidgets();

    document.addEventListener('DOMContentLoaded', initializeWidgets, { once: true });
    window.addEventListener('load', initializeWidgets, { once: true });
  })();

  } catch(e) { console.error(e); }
})();

(function() {
  if (!__sections__["brunito-size-guide"] && !Shopify.designMode) return;
  try {
    
  document.querySelectorAll('[data-size-guide]').forEach((guide) => {
    const select = guide.querySelector('[data-size-guide-select]');
    const panels = guide.querySelectorAll('[data-size-guide-panel]');
    const empty = guide.querySelector('[data-size-guide-empty]');
    const measurements = guide.querySelector('[data-size-guide-measurements]');
    const label = guide.querySelector('[data-size-guide-measure-label]');
    const help = guide.querySelector('[data-size-guide-measure-help]');
    const measure = guide.querySelector('[data-size-guide-measure]');
    const result = guide.querySelector('[data-size-guide-result]');
    const rules = guide.querySelectorAll('[data-size-guide-rules] span');
    const variants = guide.querySelectorAll('[data-size-guide-variants] span');
    const addButton = guide.querySelector('[data-size-guide-add]');
    const productOptions = guide.querySelectorAll('[data-size-guide-option]');
    const picker = guide.querySelector('[data-size-guide-picker]');
    const selectedTitle = guide.querySelector('[data-size-guide-selected-title]');

    const hideAddButton = () => {
      addButton.hidden = true;
      addButton.disabled = false;
      addButton.textContent = 'Añadir al carrito';
      delete addButton.dataset.variantId;
    };

    const showAddButton = (product, size) => {
      const variant = [...variants].find((item) => item.dataset.product === product && item.dataset.variantOptions.split('|').includes(size));
      if (!variant) {
        hideAddButton();
        return;
      }
      addButton.dataset.variantId = variant.dataset.variantId;
      addButton.textContent = `Añadir al carrito · talla ${size}`;
      addButton.hidden = false;
    };

    const updateGuide = () => {
      const product = select.value;
      const activePanel = guide.querySelector(`[data-size-guide-panel="${product}"]`);
      panels.forEach((panel) => panel.classList.toggle('is-active', panel === activePanel));
      productOptions.forEach((option) => {
        const isSelected = option.dataset.sizeGuideOption === product;
        option.classList.toggle('is-selected', isSelected);
        option.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
      });
      if (product) {
        selectedTitle.textContent = select.options[select.selectedIndex].text;
        picker.classList.add('has-selection');
      } else {
        selectedTitle.textContent = 'Selecciona un producto';
        picker.classList.remove('has-selection');
      }
      empty.hidden = Boolean(activePanel);
      measurements.classList.toggle('is-visible', Boolean(activePanel));
      result.classList.remove('is-visible');
      result.textContent = '';
      hideAddButton();
      if (activePanel) {
        label.textContent = activePanel.dataset.measureLabel || 'Medida principal (cm)';
        help.textContent = activePanel.dataset.measureHelp || 'Introduce la medida indicada para este producto.';
      }
    };

    select.addEventListener('change', updateGuide);
    productOptions.forEach((option) => option.addEventListener('click', () => {
      select.value = option.dataset.sizeGuideOption;
      picker.removeAttribute('open');
      updateGuide();
    }));
    guide.querySelector('[data-size-guide-button]').addEventListener('click', () => {
      const product = select.value;
      const value = Number(measure.value);
      const unit = label.textContent.toLowerCase().includes('kg') ? 'kg' : 'cm';
      if (!product) { hideAddButton(); result.textContent = 'Primero elige el producto que te interesa.'; result.classList.add('is-visible'); return; }
      if (!value) { hideAddButton(); result.textContent = `Añade tu medida principal en ${unit} para mostrarte una orientación.`; result.classList.add('is-visible'); return; }
      const productRules = [...rules].filter((item) => item.dataset.product === product);
      const rule = productRules.find((item) => value >= Number(item.dataset.min) && value <= Number(item.dataset.max));
      if (rule) {
        result.textContent = `Con una medida de ${value} ${unit}, te recomendamos la talla ${rule.dataset.size}. ${rule.dataset.copy}`;
        showAddButton(product, rule.dataset.size);
      } else if (productRules.length) {
        hideAddButton();
        const ranges = productRules.map((item) => `${item.dataset.min}–${item.dataset.max} ${unit}`).join(' o ');
        result.textContent = `Con una medida de ${value} ${unit}, estás fuera del rango recomendado (${ranges}). Consulta la tabla y escríbenos si necesitas ayuda antes de comprar.`;
      } else {
        hideAddButton();
        result.textContent = 'Consulta la tabla de medidas de este producto. Si sigues teniendo dudas, nuestro equipo estará encantado de ayudarte.';
      }
      result.classList.add('is-visible');
    });
    addButton.addEventListener('click', async () => {
      const variantId = addButton.dataset.variantId;
      if (!variantId) return;
      addButton.disabled = true;
      addButton.textContent = 'Añadiendo al carrito…';
      try {
        const response = await fetch(guide.dataset.cartAddUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
          body: JSON.stringify({ items: [{ id: variantId, quantity: 1 }] })
        });
        if (!response.ok) throw new Error('No se pudo añadir el producto');
        window.location.assign(guide.dataset.cartUrl);
      } catch (error) {
        addButton.disabled = false;
        addButton.textContent = 'No se pudo añadir. Inténtalo de nuevo.';
      }
    });
  });

  } catch(e) { console.error(e); }
})();

(function() {
  if (!__sections__["main-collection"]) return;
  try {
    
  const url = new URL(window.location.href);
  if (url.hash) {
    document.addEventListener(
      'DOMContentLoaded',
      () => {
        const card = document.getElementById(url.hash.slice(1));
        if (card) {
          card.scrollIntoView({ behavior: 'instant' });
        }
      },
      { once: true }
    );
  }

  } catch(e) { console.error(e); }
})();
})();
